function supplyPairs({ weights, budget }) {
    let count = 0;
    for (let left = 0; left < weights.length; left++) {
        for (let right = left + 1; right < weights.length; right++) {
            if (weights[left] + weights[right] <= budget)
                count++;
        }
    }
    return count;
}

function supplyPairs({ weights, budget }) {
    let left = 0, right = weights.length - 1, count = 0;
    while (left < right) {
        if (weights[left] + weights[right] <= budget) {
            count += right - left;
            left++;
        }
        else
            right--;
    }
    return count;
}
